package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                            // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.New(0, 0)   // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.New(0, 0)        // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.New(0, 0)   // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                                // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string  // PIC ZZ,ZZ9.99 len=9
var WsNetEd string   // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var discFileLines []string
var discFileIndex int

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

// store for PIC 9(intDigits)V99 etc : truncate toward zero and keep low-order digits
func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	q := val.Truncate(int32(scale))
	// keep low order digits: modulo 10^(intDigits+scale)
	mod := pow10(intDigits + scale)
	// scaled integer representation
	scaled := q.Shift(int32(scale)).IntPart() // fits in int64 for these sizes
	rem := scaled % mod
	return decimal.New(rem, int32(-scale))
}

func storeInt(val int64, digits int) int64 {
	mod := pow10(digits)
	return val % mod
}

// format numeric-edited picture with Z , . 9
func formatEdited(val decimal.Decimal, picture string) string {
	// find dot
	dotPos := strings.Index(picture, ".")
	var intPic, decPic string
	var nInt, nDec int
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		decPic = picture[dotPos+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			nInt++
		}
	}
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			nDec++
		}
	}
	// quantize to nDec
	q := val.Truncate(int32(nDec))
	absQ := q.Abs()
	scaled := absQ.Shift(int32(nDec)).IntPart()
	// low-order truncation for integer overflow: intPart modulo 10^nInt
	powInt := pow10(nInt)
	powDec := pow10(nDec)
	intPart := int64(0)
	fracPart := int64(0)
	if nDec > 0 {
		intPart = scaled / powDec
		fracPart = scaled % powDec
		intPart = intPart % powInt
	} else {
		intPart = scaled % powInt
	}
	intDigitsStr := fmt.Sprintf("%0*d", nInt, intPart)
	fracDigitsStr := ""
	if nDec > 0 {
		fracDigitsStr = fmt.Sprintf("%0*d", nDec, fracPart)
	}

	// build output rune array from picture
	out := []rune(picture)

	// fill integer digit placeholders
	di := nInt - 1
	for i := len(intPic) - 1; i >= 0; i-- {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			out[i] = rune(intDigitsStr[di])
			di--
		} else {
			// comma stays
			out[i] = c
		}
	}
	// fill decimal part
	if dotPos >= 0 {
		// dot already at out[dotPos]
		for i := 0; i < len(decPic); i++ {
			c := decPic[i]
			if c == 'Z' || c == '9' {
				// need index in fracDigitsStr: sequential
				// count digit placeholders up to i
				digitIdx := 0
				for k := 0; k < i; k++ {
					if decPic[k] == 'Z' || decPic[k] == '9' {
						digitIdx++
					}
				}
				// actually simpler: iterate placeholders in order
				// we can map placeholder order
				out[dotPos+1+i] = rune(fracDigitsStr[digitIdx])
			} else {
				out[dotPos+1+i] = c
			}
		}
	}
	// suppression for integer part
	foundNonZero := false
	// first pass: detect any non-zero digit will be found, but we need sequential scan
	for i := 0; i < len(intPic); i++ {
		pc := intPic[i]
		oc := out[i]
		if pc == 'Z' {
			if oc != '0' {
				foundNonZero = true
			} else {
				if !foundNonZero {
					out[i] = ' '
				} else {
					// zero after non-zero stays '0'
				}
			}
		} else if pc == '9' {
			if oc != '0' {
				foundNonZero = true
			}
			// mandatory 9 never suppressed even if zero and no non-zero
		} else if pc == ',' {
			if !foundNonZero {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	return string(out)
}

func formatPIC9(val int64, digits int) string {
	// zero padded to digits, low-order truncation already done
	// for negative? not needed
	if val < 0 {
		val = -val
	}
	return fmt.Sprintf("%0*d", digits, val)
}

func parsePriceField(s string) decimal.Decimal {
	// s is digits only, 7 chars, implied 2 decimals
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.New(0, 0)
	}
	// may contain spaces? Remove spaces
	t = strings.TrimSpace(t)
	// keep only digits and sign?
	// parse as integer
	// if contains non-digit, treat as 0? Assume digits.
	var n int64 = 0
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	// if original field had spaces inside? ignore
	return decimal.New(n, -2)
}

func parsePctField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var n int64 = 0
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return n
}

func mainPara() {
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty (COBOL would error, but we exit)
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// preserve spaces: Scanner strips newline but keeps other spaces
	// Need to handle long lines; increase buffer
	const maxCapacity = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)
	discFileLines = []string{}
	for scanner.Scan() {
		line := scanner.Text()
		// strip trailing \r for CRLF
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		discFileLines = append(discFileLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	discFileIndex = 0
	WsEofFlag = "N"
	performReadPara()
	for !isInputDone() {
		performProcessPara()
	}
	// CLOSE DISC-FILE (deferred)
	performSummaryPara()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func performReadPara() {
	readPara()
}
func performProcessPara() {
	processPara()
}
func performSummaryPara() {
	summaryPara()
}

func readPara() {
	if discFileIndex >= len(discFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := discFileLines[discFileIndex]
	discFileIndex++
	// pad with spaces on right to record length 15
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	discRec.DrItem = raw[0:6]
	discRec.DrPrice = parsePriceField(raw[6:13])
	discRec.DrPct = parsePctField(raw[13:15])
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	// multiply before divide
	mul := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	div := mul.Shift(-2) // /100
	rounded := div.Round(2)
	WsDiscount = storeDecimal(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	q := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(q, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(sum, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = storeInt(WsCount+1, 3)

	// MOVE DR-PRICE TO WS-PRICE-ED etc
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-ITEM is X(6) exactly, WS edited fields are already correct width with spaces
	// DR-PCT is 9(2) zero-padded
	pctStr := formatPIC9(discRec.DrPct, 2)
	// Build line: DR-ITEM + " " + WS-PRICE-ED + " " + pctStr + "% " + WS-DISC-ED + " " + WS-NET-ED
	// DISPLAY writes operands concatenated followed by newline
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	performReadPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatPIC9(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	mainPara()
}

